<?php require_once "includes/header.php"; ?>
<?php
$porPagina = 9;
$paginaAtual = isset($_GET['pagina']) ? max(1, (int)$_GET['pagina']) : 1;
$offset = ($paginaAtual - 1) * $porPagina;
$pesquisa = trim($_GET['pesquisa'] ?? '');
$categoria = trim($_GET['categoria'] ?? '');
$ano = trim($_GET['ano'] ?? '');
$where = ["ativo = 1"];
$params = [];
if ($pesquisa !== '') { $where[] = "(titulo LIKE ? OR descricao LIKE ? OR tags LIKE ?)"; $params[] = "%$pesquisa%"; $params[] = "%$pesquisa%"; $params[] = "%$pesquisa%"; }
if ($categoria !== '') { $where[] = "categoria = ?"; $params[] = $categoria; }
if ($ano !== '') { $where[] = "ano = ?"; $params[] = $ano; }
$whereSql = implode(" AND ", $where);
$stmtTotal = $pdo->prepare("SELECT COUNT(*) FROM assembleia_documentos WHERE $whereSql");
$stmtTotal->execute($params);
$totalDocumentos = (int)$stmtTotal->fetchColumn();
$totalPaginas = max(1, ceil($totalDocumentos / $porPagina));
$stmt = $pdo->prepare("SELECT * FROM assembleia_documentos WHERE $whereSql ORDER BY destaque DESC, data_documento DESC, criado_em DESC LIMIT $porPagina OFFSET $offset");
$stmt->execute($params);
$documentos = $stmt->fetchAll(PDO::FETCH_ASSOC);
$categorias = $pdo->query("SELECT DISTINCT categoria FROM assembleia_documentos WHERE ativo = 1 AND categoria IS NOT NULL AND categoria <> '' ORDER BY categoria ASC")->fetchAll(PDO::FETCH_COLUMN);
$anos = $pdo->query("SELECT DISTINCT ano FROM assembleia_documentos WHERE ativo = 1 AND ano IS NOT NULL AND ano <> '' ORDER BY ano DESC")->fetchAll(PDO::FETCH_COLUMN);
$totalAtas = (int)$pdo->query("SELECT COUNT(*) FROM assembleia_documentos WHERE ativo = 1 AND categoria = 'Atas'")->fetchColumn();
$totalEditais = (int)$pdo->query("SELECT COUNT(*) FROM assembleia_documentos WHERE ativo = 1 AND categoria = 'Editais'")->fetchColumn();
$totalConvocatorias = (int)$pdo->query("SELECT COUNT(*) FROM assembleia_documentos WHERE ativo = 1 AND categoria = 'Convocatórias'")->fetchColumn();
?>
<style>
