g,#fff,#f8fafc);border:1px solid #e5e7eb;border-radius:24px;padding:20px;box-shadow:0 14px 36px rgba(15,23,42,.06);transition:.22s ease}.doc-card:hover{transform:translateY(-4px);box-shadow:0 22px 50px rgba(15,23,42,.10)}.doc-top{display:flex;justify-content:space-between;gap:12px;margin-bottom:16px}.doc-icon{width:54px;height:54px;border-radius:18px;display:grid;place-items:center;background:#242A30;color:white;font-weight:900;box-shadow:0 14px 28px rgba(36,42,50,.20)}.doc-badge{display:inline-flex;align-items:center;height:30px;padding:0 10px;border-radius:999px;background:#fef3c7;color:#92400e;font-size:12px;font-weight:900}.doc-card h3{color:#11151B;margin:0 0 10px;font-size:20px;line-height:1.25}.doc-card p{color:#64748b;line-height:1.6;margin:0 0 16px}.doc-meta{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:18px}.doc-meta span{background:#eef2f7;color:#334155;border-radius:999px;padding:7px 10px;font-size:12px;font-weight:900}.doc-actions{display:flex;gap:10px;flex-wrap:wrap}.empty-docs{background:#f8fafc;border:1px dashed #cbd5e1;border-radius:22px;padding:30px;color:#64748b;font-weight:800}.paginacao-docs-pro{display:flex;gap:8px;flex-wrap:wrap;align-items:center;justify-content:center;margin-top:24px}.paginacao-docs-pro a,.paginacao-docs-pro span{min-width:42px;height:42px;display:grid;place-items:center;border-radius:14px;background:#f8fafc;border:1px solid #e5e7eb;color:#11151B;text-decoration:none;font-weight:900}.paginacao-docs-pro a.active{background:#242A30;color:white}@media(max-width:1100px){.docs-stats,.docs-grid{grid-template-columns:repeat(2,1fr)}.docs-filtros{grid-template-columns:1fr 1fr}}@media(max-width:700px){.docs-stats,.docs-grid,.docs-filtros{grid-template-columns:1fr}}
</style>
<section class="assembleia-docs-hero"><div class="container"><span class="docs-kicker">Assembleia de Freguesia</span><h1>Documentos da Assembleia</h1><p>Consulte atas, editais, convocatórias, deliberações e documentos oficiais publicados pela Assembleia de Freguesia.</p></div></section>
<section class="section"><div class="container"><div class="docs-stats"><div class="docs-stat"><span><i class="bi bi-file-earmark-text-fill"></i></span><strong><?= (int)$totalDocumentos ?></strong><small>Documentos publicados</small></div><div class="docs-stat"><span><i class="bi bi-file-earmark-text-fill"></i></span><strong><?= (int)$totalAtas ?></strong><small>Atas</small></div><div class="docs-stat"><span><i class="bi bi-megaphone-fill"></i></span><strong><?= (int)$totalEditais ?></strong><small>Editais</small></div><div class="docs-stat"><span><i class="bi bi-calendar-event-fill"></i></span><strong><?= (int)$totalConvocatorias ?></strong><small>Convocatórias</small></div></div><div class="docs-filter-card"><h2>Pesquisar documentos</h2><form method="GET" class="docs-filtros"><input type="text" name="pesquisa" placeholder="Pesquisar por título, descrição ou tags..." value="<?= htmlspecialchars($pesquisa) ?>"><select name="categoria"><option value="">Todas as categorias</option><?php foreach ($categorias as $cat): ?><option value="<?= htmlspecialchars($cat) ?>" <?= $categoria === $cat ? 'selected' : '' ?>><?= htmlspecialchars($cat) ?></option><?php endforeach; ?></select><select name="ano"><option value="">Todos os anos</option><?php foreach ($anos as $a): ?><option value="<?= htmlspecialchars($a) ?>" <?= $ano == $a ? 'selected' : '' ?>><?= htmlspecialchars($a) ?></option><?php endforeach; ?></select><button class="hero-btn" type="submit">Filtrar</button><a class="hero-btn" href="assembleia-documentos.php">Limpar</a></form></div><div class="docs-list-card"><div class="docs-topo"><h2>Documentos publicados</h2><span><?= (int)$totalDocumentos ?> documento(s)</span></div><?php if (!empty($documentos)): ?><div class="docs-grid"><?php foreach ($documentos as $d): ?><?php $ficheiro=htmlspecialchars($d['ficheiro']); $ext=strtoupper(pathinfo($ficheiro, PATHINFO_EXTENSION)); $url="/uploads/assembleia/".$ficheiro; ?><article class="doc-card"><div class="doc-top"><div class="doc-icon"><?= htmlspecialchars($ext ?: 'DOC') ?></div><?php if (!empty($d['destaque'])): ?><span class="doc-badge">Destaque</span><?php endif; ?></div><h3><?= htmlspecialchars($d['titulo']) ?></h3><?php if (!empty($d['descricao'])): ?><p><?= htmlspecialchars($d['descricao']) ?></p><?php endif; ?><div class="doc-meta"><span><?= htmlspecialchars($d['categoria']) ?></span><?php if (!empty($d['ano'])): ?><span><?= htmlspecialchars($d['ano']) ?></span><?php endif; ?><?php if (!empty($d['data_documento'])): ?><span><?= date('d/m/Y', strtotime($d['data_documento'])) ?></span><?php endif; ?></div><div class="doc-actions"><a class="hero-btn" href="<?= $url ?>" target="_blank">Ver documento</a><a class="hero-btn" href="<?= $url ?>" download>Download</a></div></article><?php endforeach; ?></div><?php if ($totalPaginas > 1): ?><div class="paginacao-docs-pro"><?php function linkPaginaDocs($pagina,$texto=null){$query=$_GET;$query['pagina']=$pagina;return '<a href="?'.http_build_query($query).'">'.($texto ?? $pagina).'</a>';} ?><?php if ($paginaAtual > 1): ?><?= linkPaginaDocs($paginaAtual - 1, '‹') ?><?php endif; ?><?php for ($i=1;$i<=$totalPaginas;$i++): ?><?php if ($i==1 || $i==$totalPaginas || abs($i-$paginaAtual)<=2): ?><a class="<?= $i == $paginaAtual ? 'active' : '' ?>" href="?<?= http_build_query(array_merge($_GET, ['pagina'=>$i])) ?>"><?= $i ?></a><?php elseif ($i==2 || $i==$totalPaginas-1): ?><span>...</span><?php endif; ?><?php endfor; ?><?php if ($paginaAtual < $totalPaginas): ?><?= linkPaginaDocs($paginaAtual + 1, '›') ?><?php endif; ?></div><?php endif; ?><?php else: ?><div class="empty-docs">Não foram encontrados documentos com os filtros selecionados.</div><?php endif; ?></div></div></section>
